"""Packet record for the staged scheduler."""


class Pkt:
    """One packet attempt.

    ``rank`` is assigned by the policy on the enqueue attempt and is immutable
    afterwards, ``oid`` is the immutable tie ordinal (the zero-based index of
    the enqueue in the complete event array) and ``bank`` is the selected
    physical PIFO.  ``slot`` is the packet's position in its bank's staging
    FIFO; the staging list only ever appends, so the slot never moves and can
    be used for O(1) cancellation.
    """

    __slots__ = ('pktid', 'flowid', 'length', 'flow_size',
                 'rank', 'oid', 'bank', 'slot')

    def __init__(self, pktid, flowid, length, flow_size):
        self.pktid = pktid
        self.flowid = flowid
        self.length = length
        self.flow_size = flow_size
        self.rank = 0
        self.oid = 0
        self.bank = 0
        self.slot = 0

    def __repr__(self):
        return ('Pkt(id=%r, flow=%r, length=%r, rank=%r, oid=%r, bank=%r)'
                % (self.pktid, self.flowid, self.length, self.rank,
                   self.oid, self.bank))
