"""Rank policies: FIFO, strict priority, smallest flow size first and quantized
WFQ finish tags.  All arithmetic is exact integer arithmetic.

Every enqueue attempt is ranked, including attempts that are later rejected by
admission, so FIFO/WFQ rank state advances on rejected attempts too.  Weight
updates affect future attempts only.  Policy state participates in checkpoint
branches: mutable tables are copy-on-write against the scheduler version, so a
checkpoint stores table references and never needs a table-sized copy unless the
table really changes after the checkpoint was taken.
"""

from packet import Pkt

QUANT = 1048576


class SchedulingAlgorithm:
    def __init__(self, *args, **kwargs):
        pass

    def rank_cal(self, pkt: Pkt):
        raise NotImplementedError("Subclasses should implement this method.")

    def post_dequeue(self, pkt: Pkt, rank):
        pass

    def set_weight(self, flow, weight):
        raise NotImplementedError('weight updates apply to the wfq policy')

    def certificate(self):
        raise NotImplementedError("Subclasses should implement this method.")

    def snapshot(self):
        raise NotImplementedError("Subclasses should implement this method.")

    def restore(self, state, ver):
        raise NotImplementedError("Subclasses should implement this method.")


class FifoAlgorithm(SchedulingAlgorithm):
    def __init__(self):
        super().__init__()
        self.time = 0

    def rank_cal(self, pkt: Pkt):
        self.time += 1
        return self.time

    def post_dequeue(self, pkt: Pkt, rank):
        pass

    def set_weight(self, flow, weight):
        pass

    def certificate(self):
        return {'kind': 'fifo', 'time': self.time}

    def snapshot(self):
        return self.time

    def restore(self, state, ver):
        self.time = state


class SpAlgorithm(SchedulingAlgorithm):
    def __init__(self, flowid2pri):
        super().__init__()
        self.flowid2pri = dict(flowid2pri)

    def rank_cal(self, pkt: Pkt):
        return self.flowid2pri.get(pkt.flowid, 0)

    def post_dequeue(self, pkt: Pkt, rank):
        pass

    def set_weight(self, flow, weight):
        pass

    def certificate(self):
        return {'kind': 'sp',
                'levels': [list(item) for item in sorted(self.flowid2pri.items())]}

    def snapshot(self):
        return None

    def restore(self, state, ver):
        pass


class pFabricAlgorithm(SchedulingAlgorithm):
    """Smallest flow size first."""

    def __init__(self):
        super().__init__()

    def rank_cal(self, pkt: Pkt):
        return pkt.flow_size

    def post_dequeue(self, pkt: Pkt, rank):
        pass

    def set_weight(self, flow, weight):
        pass

    def certificate(self):
        return {'kind': 'sff'}

    def snapshot(self):
        return None

    def restore(self, state, ver):
        pass


class WFQAlgorithm(SchedulingAlgorithm):
    def __init__(self, flowid2weight, ver=0):
        super().__init__()
        self.flowid2weight = dict(flowid2weight)
        self.flowid2finish = {flow: 0 for flow in self.flowid2weight}
        self.virtual_time = 0
        self.ver = ver
        self.weight_stamp = ver
        self.finish_stamp = ver

    def _weights(self):
        if self.weight_stamp != self.ver:
            self.flowid2weight = dict(self.flowid2weight)
            self.weight_stamp = self.ver
        return self.flowid2weight

    def _finish(self):
        if self.finish_stamp != self.ver:
            self.flowid2finish = dict(self.flowid2finish)
            self.finish_stamp = self.ver
        return self.flowid2finish

    def rank_cal(self, pkt: Pkt):
        flowid = pkt.flowid
        weights = self._weights()
        finish = self._finish()
        weight = weights.get(flowid)
        if weight is None:
            weight = 1
            weights[flowid] = 1
            finish.setdefault(flowid, 0)
        tag = finish.get(flowid, 0)
        if self.virtual_time > tag:
            tag = self.virtual_time
        length = pkt.length
        tag += (length * QUANT + weight - 1) // weight
        finish[flowid] = tag
        pkt.rank = tag
        return tag

    def post_dequeue(self, pkt: Pkt, rank):
        if rank > self.virtual_time:
            self.virtual_time = rank

    def set_weight(self, flow, weight):
        self._weights()[flow] = weight
        self._finish().setdefault(flow, 0)

    def certificate(self):
        return {'kind': 'wfq',
                'virtual_time': self.virtual_time,
                'weights': [list(item) for item in sorted(self.flowid2weight.items())],
                'finish': [list(item) for item in sorted(self.flowid2finish.items())]}

    def snapshot(self):
        return (self.virtual_time, self.flowid2weight, self.flowid2finish)

    def restore(self, state, ver):
        self.virtual_time, self.flowid2weight, self.flowid2finish = state
        # Keep the stamps: the version has advanced, so the next mutation of
        # either table copies it instead of disturbing the checkpoint.
        self.ver = ver


def make_policy(spec, ver=0):
    kind = spec['kind']
    if kind == 'fifo':
        return FifoAlgorithm()
    if kind == 'sp':
        return SpAlgorithm(spec['levels'])
    if kind == 'sff':
        return pFabricAlgorithm()
    if kind == 'wfq':
        return WFQAlgorithm(spec['weights'], ver)
    raise ValueError('unknown policy kind: %r' % (kind,))
